257	  const shutdown = async (reason: string, code: number): Promise<number> =>
258	  {
259	    if (shuttingDown)
260	    {
261	      return code;
262	    }
263	
264	    shuttingDown = true;
265	    audioCapture?.stop();
266	
267	    if (session !== undefined)
268	    {
269	      try
270	      {
271	        await session.stop(reason);
272	      }
273	      catch (stopError)
274	      {
275	        const message =
276	          stopError instanceof Error ? stopError.message : String(stopError);
277	        console.error(`Failed to stop session: ${message}`);
278	        runtimeLogger.LogError("session_stop_failed", { reason, error: message });
279	      }
280	    }
281	
282	    database.close();
283	    runtimeLogger.Log("cli_shutdown", { reason, exit_code: code });
284	    runtimeLogger.Close();
285	    return code;
286	  };
287	
288	  const agentStartConfig: AgentStartConfig = {
289	    systemPrompt,
290	    initialContext,
291	    toolCallSet: BuildToolCallSet(options.toolNames),
292	    model: options.model,
293	    turnMode: x_defaultTurnMode,
294	    onEvent: (event, info) =>
295	    {
296	      logEventLine({
297	        sessionId: info.sessionId,
298	        direction: info.direction,
299	        event,
300	      });
301	    },
302	    onSessionEnded: (info) =>
303	    {
304	      runtimeLogger.Log("realtime_session_ended", {
305	        session_id: info.sessionId,
306	        reason: info.reason,
307	      });
308	
309	      if (info.reason === x_connectionLostReason)
310	      {
311	        console.error("Realtime connection lost; session ended.");
312	        runtimeLogger.LogError("realtime_connection_lost", {
313	          session_id: info.sessionId,
314	        });
315	        void shutdown(info.reason, 1).then((exitCode) =>
316	        {
317	          if (deps.registerSignalHandlers !== false)
318	          {
319	            process.exit(exitCode);
320	          }
321	        });
322	      }
323	    },
324	    onToolLifecycle: (notification) =>
325	    {
