398	  catch (error)
399	  {
400	    const message = error instanceof Error ? error.message : String(error);
401	    runtimeLogger.LogError("microphone_setup_failed", { error: message });
402	    await shutdown("audio_setup_error", 1);
403	    throw error;
404	  }
405	
406	  return {
407	    session,
408	    audioCapture,
409	    database,
410	    runtimeLogger,
411	    shutdown,
412	  };
413	}
