415	export async function RunCli(argv: string[], deps: CliRunDeps = {}): Promise<number>
416	{
417	  let parsed: ParseCliResult;
418	  try
419	  {
420	    parsed = ParseCliArgs(argv);
421	  }
422	  catch (error)
423	  {
424	    if (error instanceof CliUsageError)
425	    {
426	      console.error(error.message);
427	      return 1;
428	    }
429	
430	    throw error;
431	  }
432	
433	  if (parsed.action === "list_input_devices")
434	  {
435	    const listDevices = deps.listInputDevices ?? ListInputDevices;
436	    const formatDevices = deps.formatInputDeviceList ?? FormatInputDeviceList;
437	    console.log(formatDevices(listDevices()));
438	    return 0;
439	  }
440	
441	  const loadConfig = deps.loadConfig ?? LoadRealtimeAgentConfig;
442	  const loadApiKey = deps.loadApiKey ?? LoadOpenAiApiKey;
443	  const createRuntimeLogger = deps.createRuntimeLogger ?? CreateRuntimeLogger;
444	
445	  let agentConfig: ResolvedRealtimeAgentConfig;
446	  let apiKey: string;
447	  let runtimeLogger: RuntimeLogger;
448	
449	  try
450	  {
451	    agentConfig = await loadConfig({ repoRoot: deps.repoRoot });
452	    apiKey = await loadApiKey({ repoRoot: deps.repoRoot });
453	    runtimeLogger = createRuntimeLogger({
454	      logPath: agentConfig.runtimeLogPath,
455	      repoRoot: deps.repoRoot,
456	    });
457	  }
458	  catch (error)
459	  {
460	    if (error instanceof ConfigLoadError)
461	    {
462	      console.error(error.message);
463	      return 1;
464	    }
465	
466	    throw error;
467	  }
468	
469	  const resolvedOptions = ResolveCliRunOptions(parsed.options, agentConfig);
470	
471	  try
472	  {
473	    const runtime = await StartCliRuntime(resolvedOptions, {
474	      ...deps,
475	      apiKey,
476	      agentConfig,
477	      runtimeLogger,
478	    });
479	
480	    if (deps.registerSignalHandlers === false)
481	    {
482	      return 0;
483	    }
484	
485	    return await new Promise<number>((resolve) =>
486	    {
487	      const onSignal = (): void =>
488	      {
489	        void runtime.shutdown("signal", 0).then(resolve);
490	      };
491	
492	      process.once("SIGINT", onSignal);
493	      process.once("SIGTERM", onSignal);
494	    });
495	  }
496	  catch (error)
497	  {
498	    if (error instanceof CliUsageError)
499	    {
500	      console.error(error.message);
501	      return 1;
502	    }
503	
504	    if (error instanceof RealtimeTransportError)
505	    {
506	      console.error(error.message);
507	      return 1;
508	    }
509	
510	    const message = error instanceof Error ? error.message : String(error);
511	    if (message.includes("ENOENT") || message.includes("no such file"))
512	    {
513	      console.error(`Failed to read prompt or context file: ${message}`);
514	      return 1;
515	    }
516	
517	    console.error(message);
518	    return 1;
519	  }
520	}
